// Build-time access to src/data/class-details.json (generated by research/class-data.mjs from the
// official class pages), with the checks the class components rely on.
import details from '../data/class-details.json';

export interface Attr {
	name: string;
	value?: string;
	flag?: boolean;
}
export interface Stage {
	stage: 'Base' | 'I' | 'II' | 'III' | 'Total';
	label: string | null;
	attrs: Attr[];
}
export interface AttrGroup {
	name: string | null;
	stages: Stage[];
}
export interface ClassDetails {
	source: string;
	tagline: string;
	profile: string | null;
	benefitsFrom: string[];
	doesNotUse: string[];
	mentorEpithet: string | null;
	unlockJourney: string | null;
	evolutions: { grade: string; title: string; journey: string; tribute: number }[];
	attributes: AttrGroup[];
	defaultAttributes: { mastery: string[]; blood: string[] };
	commands: { cmd: string; ptDescription: string }[];
}

const all = details as Record<string, ClassDetails>;

export function classDetails(id: string): ClassDetails {
	const d = all[id];
	if (!d) throw new Error(`No class details for "${id}" (see src/data/class-details.json)`);
	return d;
}

const num = (v: string) => {
	const m = v.match(/^([+-])(\d+(?:\.\d+)?)(%?)$/);
	return m ? (m[1] === '-' ? -1 : 1) * Number(m[2]) : NaN;
};

/** Attributes whose published Total differs from Base + I + II + III, with the computed sum. */
export function totalMismatches(group: AttrGroup): Map<string, number> {
	const out = new Map<string, number>();
	const total = group.stages.find((s) => s.stage === 'Total');
	if (!total) return out;
	for (const a of total.attrs) {
		if (a.flag || !a.value) continue;
		const sum = group.stages
			.filter((s) => s.stage !== 'Total')
			.flatMap((s) => s.attrs)
			.filter((x) => x.name === a.name && x.value)
			.reduce((t, x) => t + num(x.value!), 0);
		if (Math.abs(sum - num(a.value)) > 1e-9) out.set(a.name, Math.round(sum * 100) / 100);
	}
	return out;
}
